import java.util.*;

class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> result = new ArrayList<>();
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> 
            (nums1[a[0]] + nums2[a[1]]) - (nums1[b[0]] + nums2[b[1]])
        );
        int m = nums1.length, n = nums2.length;
        for (int i = 0; i < Math.min(m, k); i++) {
            pq.offer(new int[]{i, 0});
        }
        while (!pq.isEmpty() && result.size() < k) {
            int[] cur = pq.poll();
            result.add(Arrays.asList(nums1[cur[0]], nums2[cur[1]]));
            if (cur[1] + 1 < n) {
                pq.offer(new int[]{cur[0], cur[1] + 1});
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<int[]> pairs = new ArrayList<>();
        int m = Math.min(nums1.length, k);
        int n = Math.min(nums2.length, k);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                pairs.add(new int[]{nums1[i], nums2[j]});
            }
        }
        Collections.sort(pairs, (a, b) -> (a[0] + a[1]) - (b[0] + b[1]));
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < Math.min(k, pairs.size()); i++) {
            result.add(Arrays.asList(pairs.get(i)[0], pairs.get(i)[1]));
        }
        return result;
    }
}
